{
  "status": "unavailable",
  "reason": "lock_held",
  "why": "This brain ({{HOME}}/.gbrain/brain.pglite) is open in another `gbrain serve` (PID {{PID}}, started {{TIME}}), usually started by another agent session, so this server cannot open it. That is expected when two agent sessions (for example Claude Code and Codex) are open at once: nothing is broken and nothing needs fixing.",
  "brain_path": "{{HOME}}/.gbrain/brain.pglite",
  "config_path": "{{HOME}}/.gbrain/config.json",
  "lock_owner": {
    "pid": "{{PID}}",
    "transport": "stdio",
    "serve": true,
    "started_at": "{{TIME}}"
  },
  "expected": true,
  "fix": {
    "mcp": {
      "tool": "gbrain_status",
      "arguments": {}
    },
    "consent": [],
    "actor": "user",
    "why": "Nothing needs fixing: once the session that owns the brain (another `gbrain serve` (PID {{PID}}, started {{TIME}}), usually started by another agent session) ends, call gbrain_status again and this server opens the brain in place (re-checked at most every 5 s). If your client does not refresh its tool list after recovery, restart this MCP server.",
    "user_message": "Your gbrain brain is open in another gbrain serve (PID {{PID}}, started {{TIME}}), usually started by another agent session. That's expected with two agent sessions open, and nothing needs fixing: session-start context still reaches this session through that server, and this session's memory tools come back once that session ends. If you want both sessions to use memory tools at the same time, I can set up one shared gbrain server. Want that?",
    "requires_exclusive": false
  },
  "user_message": "Your gbrain brain is open in another gbrain serve (PID {{PID}}, started {{TIME}}), usually started by another agent session. That's expected with two agent sessions open, and nothing needs fixing: session-start context still reaches this session through that server, and this session's memory tools come back once that session ends. If you want both sessions to use memory tools at the same time, I can set up one shared gbrain server. Want that?",
  "decisions": [
    {
      "id": "lock_recovery",
      "question": "Two agent sessions want the same brain. Close the other session, or share one HTTP server?",
      "options": [
        {
          "id": "close_owner",
          "label": "Close another gbrain serve (PID {{PID}}, started {{TIME}}), usually started by another agent session; this server recovers on the next gbrain_status call."
        },
        {
          "id": "share_http",
          "label": "Run one shared `gbrain serve --http` and connect every harness to it (writes harness config, mints tokens); the full plan is share_http_plan.",
          "argv": [
            "kill",
            "{{PID}}"
          ]
        }
      ],
      "default": "close_owner",
      "default_reason": "Nothing is installed or reconfigured; the brain comes back as soon as the other session ends."
    }
  ],
  "share_http_plan": {
    "argv": [
      "kill",
      "{{PID}}"
    ],
    "command": "kill {{PID}}",
    "consent": [],
    "actor": "user",
    "why": "Stop another `gbrain serve` (PID {{PID}}, started {{TIME}}), usually started by another agent session first (or quit that session); the shared server needs the brain's single-writer lock.",
    "requires_exclusive": false,
    "then": {
      "argv": [
        "gbrain",
        "serve",
        "--http"
      ],
      "command": "gbrain serve --http",
      "consent": [
        "persistent_install"
      ],
      "actor": "user",
      "why": "Run ONE shared HTTP server for every agent session on this machine (keep it running, e.g. under autopilot or a terminal).",
      "requires_exclusive": true,
      "then": {
        "argv": [
          "gbrain",
          "bootstrap",
          "harness",
          "--harness",
          "all",
          "--yes"
        ],
        "command": "gbrain bootstrap harness --harness all --yes",
        "consent": [
          "persistent_install",
          "credentials"
        ],
        "actor": "user",
        "why": "Mints one bearer token per detected harness through the running HTTP server and rewrites each harness MCP entry to it (each stdio entry keeps working until its harness is rewired).",
        "user_message": "I can connect your agent apps to the shared gbrain server so every session uses memory at once. That stores an access token in each app's config and pre-approves gbrain's tools. OK?",
        "verify": {
          "argv": [
            "gbrain",
            "doctor",
            "--only",
            "harness_wiring",
            "--json"
          ]
        },
        "docs": "{{DOCS_BASE}}/docs/guides/remote-mcp.md",
        "requires_exclusive": false
      }
    }
  },
  "checked_at": "{{TIME}}",
  "contract_version": 1,
  "surface": "full",
  "surface_source": "default"
}
